INSERT INTO `articles` (`id`, `category_id`, `title`, `cover`, `summary`, `content`, `tags`, `author`, `view_count`, `status`, `publish_at`, `admin_id`, `created_at`, `updated_at`, `deleted_at`)
VALUES
	(1,1,'Invisalign是如何成为全球最大的3D打印机用户的','{{SITE_URL}}/storage/uploads/images/20260319/69bc17b38d60c.jpg','Align Technology 的首席执行官 Joe Hogan（一位塑料专家）表示，你不应该戴着牙套吃东西，也不需要每晚都佩戴保持器。','<p>乔·霍根每天都能看到灿烂的笑容。当人们问他在哪里工作时，他总是回答"Align Technology"，而人们往往会追问："那是什么？"这家市值120亿美元的公司正是Invisalign隐形矫正器的幕后推手。Invisalign是一种隐形牙套，每天佩戴约22小时，虽然过程痛苦且价格昂贵，但它却能强行矫正牙齿，使其排列整齐。经过数月甚至数年的磨牙，这种隐形矫正器承诺能让人们拥有自信的笑容。霍根亲眼见证了所有Invisalign矫正器的使用过程，并且渴望看到更多。</p><p>Align公司正着手进行自29年前由两位斯坦福商学院的同学创立以来规模最大的生产方式改革。该公司正准备开始直接3D打印其核心产品——隐形矫正器，从而摒弃霍根所说的耗时更长、浪费更多的模具制作流程。如果转型成功，从长远来看，这将降低成本，使治疗更加经济实惠，让更多人能够享受到Invisalign的矫正服务，并提升Align公司的利润。</p>','[\"科技\"]','',7,1,'2026-03-19 23:30:47',1,'2026-03-19 23:26:55','2026-03-19 23:26:55',NULL),
	(2,1,'借助 Metaflow，Netflix 的机器学习和人工智能开发体验将得到极大提升。','{{SITE_URL}}/storage/uploads/images/20260319/69bc18bee66de.jpg','Metaflow 是我们于 2019 年创建并开源的一个框架，如今已为 Netflix 和众多其他公司的各种机器学习和人工智能系统提供支持。它深受用户喜爱，因为它能帮助他们将机器学习/人工智能工作流程从原型阶段推进到生产阶段，使他们能够专注于构建尖端系统，为全球观众带来欢乐和娱乐。','<p>Metaflow 使用户能够：</p><p>通过最大限度地减少摩擦，快速迭代和发布</p><p>以极低的开销，在 Netflix 规模的生产环境中可靠地运行系统。</p><p>Metaflow 与众多久经考验的工具协同工作，以实现第二个目标——其中包括 Maestro，我们新近开源的工作流编排器，它为 Netflix 几乎所有机器学习和人工智能系统提供支持，同时也是 Metaflow 自身的基石。</p><p>在本文中，我们将重点介绍第一个目标，并介绍 Metaflow 的一项新功能 Spin，它可以帮助用户加速迭代开发流程。阅读完本文后，您将深入了解 Spin 的功能，并学习如何使用 Metaflow 2.19 亲自体验它。</p><p>为了理解我们如何改进机器学习和人工智能开发体验，了解这些工作流程与传统软件工程有何不同至关重要。</p><p>机器学习和人工智能开发不仅围绕代码展开，还围绕数据和模型展开，而这些数据和模型规模庞大、可变且计算成本高昂。迭代周期可能涉及长时间运行的数据转换、模型训练以及每次运行结果略有不同的随机过程。这些特性使得快速、有状态的迭代成为高效开发的关键。</p><p>Jupyter、Observable 或 Marimo 等笔记本工具正是在此发挥了重要作用。它们能够将状态保存在内存中，使开发人员只需加载一次数据集，即可迭代地探索、转换和可视化它，而无需重新加载或从头开始重新计算。这种持久的交互式环境将原本缓慢而僵化的循环转变为流畅、探索性的工作流程，完美契合机器学习和人工智能从业者的需求。</p><p>由于机器学习和人工智能开发是计算密集型、随机性强且以数据和模型为中心的，因此，优化迭代速度的工具必须将状态管理视为首要设计考量。任何旨在改善该领域开发体验的系统都必须支持快速、增量式的实验，同时确保迭代之间的连续性。</p><p>新增：使用 spin 实现快速迭代开发</p><p>乍一看，Metaflow 代码似乎是一个工作流——类似于 Airflow——但还有另一种理解方式：每个 Metaflow @step 都充当一个检查点边界。在每个步骤结束时，Metaflow 会自动将所有实例变量持久化为工件，从而允许从该点无缝恢复执行。以下动画演示了这一行为：</p>','[\"科技\",\"AI\"]','',7,1,'2026-03-19 00:00:00',1,'2026-03-19 23:39:27','2026-03-19 23:39:27',NULL),
	(3,1,'为什么沃尔玛和OpenAI要对其智能购物协议进行改革？','{{SITE_URL}}/storage/uploads/images/20260319/69bc19817e3ad.jpg','在 OpenAI 的即时结账功能未能达到预期效果后，沃尔玛转而将其 Sparky 聊天机器人直接嵌入到 ChatGPT 和 Google Gemini 中。','<p>自去年11月以来，沃尔玛允许部分ChatGPT用户在不离开OpenAI聊天机器人界面的情况下订购有限数量的商品。沃尔玛一位执行副总裁独家向《连线》杂志透露，销售情况令人失望。</p>','[\"科技\"]','',2,1,'2026-03-19 00:00:00',1,'2026-03-19 23:43:57','2026-03-19 23:43:57',NULL),
	(4,1,'Netflix规模下的发布可观测性','{{SITE_URL}}/storage/uploads/images/20260319/69bc1a8fa533b.jpg','在 Netflix，我们每月在全球范围内推出超过一千部内容，并投入数十亿美元的年度资金。确保每部影片在我们平台上的成功上线和曝光度是我们的首要任务，因为我们的目标是将每个故事与合适的受众连接起来，从而让我们的会员满意。为了实现这一目标，我们致力于构建强大的系统，提供全面的可观测性，使我们能够对平台上的每一部影片都承担全部责任。','<p>影片上线可观测性的挑战</p><p>作为工程师，我们习惯于追踪系统指标，例如错误率、延迟和 CPU 利用率——但那些对影片成功至关重要的指标呢？</p><p>对于基本的推荐系统而言，只要用户观看的是排名靠前的标题，这两个示例页面看起来就可能相同。然而，这两个页面实际上截然不同。每个标题都凝聚了无数的心血和创意，我们的系统需要尊重这种独特性。</p><p>我们该如何弥合这种差距？我们该如何设计能够识别这些细微差别，并让每个标题都熠熠生辉、为用户带来愉悦体验的系统？</p><p>个性化系统的运营需求</p><p>在 Netflix 原创内容的早期，我们的上线团队会在午夜聚集在一起，手动核实影片是否出现在所有正确的位置。虽然这种人工操作的方式对少数影片有效，但很快就发现它无法扩展。随着 Netflix 的全球扩张和影片上线数量的激增，维持这种人工流程的运营挑战变得显而易见。</p><p>运营一个全球流媒体服务的个性化系统，意味着要处理大量关于某些影片为何在特定时间和地点出现或未出现的查询。</p><p>例如：</p><p>为什么影片 X 没有出现在特定会员的"即将上线"列表中？</p><p>为什么影片 Y 在巴西的搜索页面上找不到？</p><p>影片 Z 是否在所有产品体验中都按预期正确显示？</p><p>随着 Netflix 规模的扩大，我们面临着越来越大的挑战：如何准确、及时地回答关于影片表现和可发现性的日益复杂的查询。这导致各个团队之间分散着各种零散的脚本、运行手册和临时解决方案——这种方法既不可持续也不高效。</p>','[\"科技\"]','',7,1,'2026-03-19 00:00:00',1,'2026-03-19 23:47:29','2026-03-19 23:47:29',NULL);
